import{z as o,x as B,o as t,c as p,q as n,j as A,D as i,d as e,s as l,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"背包","description":"","frontmatter":{"title":"背包","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/knapsack.md","filePath":"cs/knapsack.md","lastUpdated":1791063341000}'),d={name:"cs/knapsack.md"};function D(C,a,m,_,u,h){const r=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=n('<h1 id="背包" tabindex="-1">背包 <a class="header-anchor" href="#背包" aria-label="Permalink to &quot;背包&quot;">​</a></h1><div class="epigraph"><p>容量是状态的一维；每件物品选或不选（或可重复）变成对这一维的转移。</p><footer>—— 据 Dantzig, Discrete-Variable Extremum Problems, 1957；CLRS 第 16、34 章相关讨论整理</footer></div><p>上一课<a href="/cs/opt-substructure">最优子结构与重叠</a>给了状态与转移的骨架。贪心课已声明 0-1 背包按密度贪心会错。本课不重讲备忘。缺口是：把<strong>容量 \\(W\\) 与物品前缀</strong>写成具体 DP，并分清分数、0-1、完全三种。算法课仍在多项式：\\(W\\) 记入输入时伪多项式；NP 课再解释「伪」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 件物品，重量 \\(w_i\\)、价值 \\(v_i\\)，容量 \\(W\\)。分数背包：可切，按 \\(v_i/w_i\\) 贪心正确（交换论证）。0-1：每件至多一次，密度贪心有反例，DP：\\(dp[i][w]\\) 为前 \\(i\\) 件、容量 \\(w\\) 的最大价值，转移用或不用第 \\(i\\) 件，\\(\\Theta(nW)\\)。完全背包：每件可用多次，内层容量递增或改转移。</p><p>缺口是这张表，不是线性规划单纯形。物品为整数、容量为整数。</p><h3 id="不是-的多项式" tabindex="-1">\\(\\Theta(nW)\\) 不是 \\(n\\) 的多项式 <a class="header-anchor" href="#不是-的多项式" aria-label="Permalink to &quot;$\\Theta(nW)$ 不是 $n$ 的多项式&quot;">​</a></h3><p>输入长度是 \\(\\Theta(n\\log W+\\sum\\log w_i)\\)，\\(W\\) 指数于位数时表是指数大。这叫伪多项式。本课仍把它当可用算法；是否 NP-完全留给后课，不要在本课重定义图灵机。</p><p><span class="marginnote">分数背包的贪心在 Dantzig 1957 已常见。0-1 的 DP 是标准教科书构造。空间可滚成一维 \\(W\\) 数组：0-1 必须逆序更新以免一件用两次。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>0-1：<code>for i</code>，<code>for w=W..w_i</code>：\\(dp[w]\\leftarrow\\max(dp[w],dp[w-w_i]+v_i)\\)（一维滚动）。完全：<code>w</code> 正序。分数：排序密度，依次装满。</p>',11)),(t(),A(s,null,{default:i(()=>[l(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FR%5B%22%E5%88%86%E6%95%B0%EF%BC%9A%E5%AF%86%E5%BA%A6%E8%B4%AA%E5%BF%83%22%5D%20--%3E%20OK1%5B%22%E5%A4%9A%E9%A1%B9%E5%BC%8F%E4%B8%94%E6%AD%A3%E7%A1%AE%22%5D%0A%20%20ZO%5B%220-1%EF%BC%9A%E5%89%8D%20i%20%E4%BB%B6%20%C3%97%20%E5%AE%B9%E9%87%8F%22%5D%20--%3E%20DP%5B%22%CE%98(nW)%20%E4%BC%AA%E5%A4%9A%E9%A1%B9%E5%BC%8F%22%5D%0A%20%20UN%5B%22%E5%AE%8C%E5%85%A8%EF%BC%9A%E5%8F%AF%E9%87%8D%E5%A4%8D%22%5D%20--%3E%20DP2%5B%22%E5%AE%B9%E9%87%8F%E6%AD%A3%E5%BA%8F%E8%BD%AC%E7%A7%BB%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"最优子结构：用了第 \\(i\\) 件则剩余是 \\(i-1\\) 件、\\(W-w_i\\) 的最优。贪心选择性质只对分数成立。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"多维容量（二维背包）加一维状态。分组、依赖是转移上的约束，骨架不变。输出方案需记录是否选用，或事后回溯。",-1)),a[6]||(a[6]=E("p",null,"与最短路：完全背包像在容量 DAG 上最长路。不要把负权环请进来：容量单调增加，无环。",-1)),a[7]||(a[7]=E("p",null,[e("第一张图分清了三种变体；这张回答最经典的坑："),E("strong",null,"一维滚动时，为什么 0-1 逆序、完全背包正序"),e("——方向决定了 \\(dp[w-w_i]\\) 读到的是「本行」还是「上一行」。")],-1)),(t(),A(s,null,{default:i(()=>[l(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20UPD%5B%22%E5%A4%84%E7%90%86%E7%AC%AC%20i%20%E4%BB%B6%EF%BC%9Adp%5Bw%5D%20%E2%86%90%20max(dp%5Bw%5D%2C%20dp%5Bw%E2%88%92w_i%5D%2Bv_i)%22%5D%20--%3E%20DIR%7B%22%E5%AE%B9%E9%87%8F%20w%20%E7%9A%84%E5%BE%AA%E7%8E%AF%E6%96%B9%E5%90%91%EF%BC%9F%22%7D%0A%20%20DIR%20--%3E%7C%22%E9%80%86%E5%BA%8F%20W%E2%86%92w_i%22%7C%20OLD%5B%22dp%5Bw%E2%88%92w_i%5D%20%E8%BF%98%E6%98%AF%E4%B8%8A%E4%B8%80%E8%A1%8C%EF%BC%88%E4%B8%8D%E5%90%AB%E7%AC%AC%20i%20%E4%BB%B6%EF%BC%89%22%5D%0A%20%20OLD%20--%3E%20OK%5B%22%E6%AF%8F%E4%BB%B6%E6%9C%80%E5%A4%9A%E7%94%A8%E4%B8%80%E6%AC%A1%EF%BC%9A%E4%BB%8D%E6%98%AF%200-1%22%5D%0A%20%20DIR%20--%3E%7C%22%E6%AD%A3%E5%BA%8F%20w_i%E2%86%92W%22%7C%20NEW%5B%22dp%5Bw%E2%88%92w_i%5D%20%E5%B7%B2%E5%90%AB%E7%AC%AC%20i%20%E4%BB%B6%22%5D%0A%20%20NEW%20--%3E%20REUSE%5B%22%E5%90%8C%E4%B8%80%E4%BB%B6%E8%A2%AB%E5%8F%8D%E5%A4%8D%E8%AE%A1%E5%85%A5%EF%BC%9A%E6%82%84%E6%82%84%E5%8F%98%E6%88%90%E5%AE%8C%E5%85%A8%E8%83%8C%E5%8C%85%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=n('<p><span class="marginnote">数字实例：容量 \\(W=100\\) 的表只有约 100 格，\\(W=10^9\\) 则要约 10 亿格——而输入里 \\(W\\) 的位数只从 3 位涨到 10 位。「表大小随数值线性、随输入长度指数」就是伪多项式的直观分量：数值翻十倍，代价翻十倍，输入只多一个字符。</span></p><p><span class="marginnote">直觉类比：一维 \\(dp\\) 数组像 Excel 里被反复覆盖的一行。从右往左刷，你引用的左边格子还是「上一件物品时的旧值」；从左往右刷，左边已经被本轮改写——同一件物品的收益被叠进旧账里，等于允许它再买一次。</span></p><p><span class="marginnote">常见误区：初学者常把 0-1 与完全背包的循环方向记反或认为「无所谓」。方向错时程序多半不报错，只是答案系统性偏大——它算的其实是一道不同的题（每件无限量）。这是背包 DP 唯一但致命的开关。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 0-1 背包 NP-完全，只承认 \\(W\\) 大时 DP 不可行。近似方案（FPTAS）不进主干。物品切分的物理含义只在分数模型。后课 P/NP 用判定版子集和作入口之一，会链回本课的伪多项式。</p><p>后课默认：分数贪心；0-1/完全用容量 DP；\\(\\Theta(nW)\\) 随 \\(W\\) 伪多项式。复杂度类下一课才命名。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分数背包贪心正确；0-1 与完全用容量 DP。</li><li>\\(\\Theta(nW)\\) 伪多项式；\\(W\\) 的位数大则爆。</li><li>一维滚动时 0-1 逆序、完全正序。</li><li>出处：Dantzig, 1957；CLRS 第 15–16 章。</li></ul>',8))])}const w=o(d,[["render",D]]);export{F as __pageData,w as default};
